package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;
import com.vandorlabs.propulsion.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Actual native conversion replay against released Source transactions, not a scalar-only surrogate. */
@EventBusSubscriber(modid="vandorlabs")
public final class PropulsionEditorChecks {
 private static final java.util.Map<String,NativePropulsionBlock> BLOCKS=new java.util.LinkedHashMap<>();private static BlockEntityType<NativePropulsionEntity> TYPE;private static int checks,profiles;private static final BlockPos BASE=new BlockPos(7768,90,7768),SAVE=BASE.south(8);
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("propulsion-editor-");}private static void need(boolean yes,String message){checks++;if(!yes)throw new AssertionError("Propulsion editor "+message+" profile="+profiles);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration{@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(var d:PropulsionDefinition.values()){var block=new NativePropulsionBlock(d.id,BlockBehaviour.Properties.of().strength(5,10),()->TYPE,BLOCKS::get);BLOCKS.put(d.id,block);h.register(ResourceLocation.parse("vandorlabs:propulsion_editor_fixture_"+d.id),block);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.of((p,s)->new NativePropulsionEntity(TYPE,p,s),BLOCKS.values().toArray(NativePropulsionBlock[]::new)).build(null);h.register(ResourceLocation.parse("vandorlabs:propulsion_editor_fixture"),TYPE);});}}
 private static BlockPos cell(Direction face,int size,int index){int right=PropulsionEmission.right(face.get3DDataValue()),up=PropulsionEmission.up(face.get3DDataValue()),x=size==1?0:index/size,y=size==1?0:index%size;return BASE.offset(PropulsionEmission.dx(right)*x+PropulsionEmission.dx(up)*y,PropulsionEmission.dy(right)*x+PropulsionEmission.dy(up)*y,PropulsionEmission.dz(right)*x+PropulsionEmission.dz(up)*y);}
 private static CompoundTag tag(JsonObject row){var tag=new CompoundTag();for(String key:new String[]{"ChannelLevel","ParticleLevel","ParticleThreshold","PropulsionSideTexture"})tag.putInt(key,row.get(key).getAsInt());for(String key:new String[]{"ManualOn","ChannelSignal","SignalBrightness","RedstoneInverted","PropulsionJoin","LightInitialized"})tag.putBoolean(key,row.get(key).getAsBoolean());var values=row.getAsJsonArray("channels");int[] channels=new int[values.size()];for(int i=0;i<channels.length;i++)channels[i]=values.get(i).getAsInt();tag.putIntArray("RedstoneChannels",channels);tag.putInt("RedstoneChannel",channels.length==0?0:channels[0]);return tag;}
 private static void write(ServerLevel w)throws Exception{w.getChunkAt(BASE);try(var lines=java.nio.file.Files.lines(java.nio.file.Path.of(System.getProperty("vandorlabs.propulsionShapeReference")))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();var block=BLOCKS.get(row.get("block").getAsString());var face=Direction.from3DDataValue(row.get("face").getAsInt());var before=row.getAsJsonArray("before");var after=row.getAsJsonArray("after");int size=before.size()==1?1:2,profile=row.get("profile").getAsInt();var owners=new java.util.ArrayList<NativePropulsionEntity>();for(int i=0;i<before.size();i++){var pos=cell(face,size,i);w.setBlock(pos,Blocks.AIR.defaultBlockState(),18);w.setBlock(pos,block.defaultBlockState().setValue(NativePropulsionBlock.FACING,face).setValue(NativePropulsionBlock.POWERED,true),18);var owner=(NativePropulsionEntity)w.getBlockEntity(pos);owner.loadWithComponents(tag(before.get(i).getAsJsonObject()),w.registryAccess());owners.add(owner);}if(profile!=11&&!(profile==10)){var draft=new NativePropulsionConfiguration.Draft(com.vandorlabs.redstone.ChannelList.of(37,41),profile!=0,3,profile!=1,profile%2==0,profile!=2,64,profile>=6,row.get("target").getAsInt(),profile%3==0,profile%3!=1,5);need(NativePropulsionConfiguration.apply(owners.getLast(),draft,null),"valid edit accepted");}for(int i=0;i<after.size();i++){var pos=cell(face,size,i);var expected=after.get(i).getAsJsonObject();var owner=(NativePropulsionEntity)w.getBlockEntity(pos);need(owner==owners.get(i)&&!owner.inert(),"same usable physical owner");need(owner.getBlockState().getBlock()==BLOCKS.get(expected.get("block").getAsString()),"Source shape");var actual=owner.saveWithoutMetadata(w.registryAccess());var wanted=tag(expected);for(String key:wanted.getAllKeys())need(wanted.get(key).equals(actual.get(key)),"Source field "+key+" expected="+wanted.get(key)+" actual="+actual.get(key)+" block="+row.get("block")+" face="+face+" profile="+profile+" member="+i);need(owner.getBlockState().getValue(NativePropulsionBlock.POWERED)==expected.get("powered").getAsBoolean(),"Source power profile="+profile);}for(int i=0;i<before.size();i++)w.setBlock(cell(face,size,i),Blocks.AIR.defaultBlockState(),18);profiles++;}}need(profiles==1944,"Source corpus coverage");}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{write(event.getServer().overworld());System.out.println("[vandorlabs][propulsion-editor] write PASS profiles="+profiles+" checks="+checks);}catch(Throwable failure){System.err.println("[vandorlabs][propulsion-editor] FAIL "+failure);failure.printStackTrace();}finally{event.getServer().halt(false);}}
}
